// Retrieve original customer information
const customer = $('Validate Customer Data').first().json;

// Fallback used when the AI step fails or returns unusable output,
// so the customer is still onboarded and flagged for a human.
function fallback(reason) {
  return {
    json: {
      ...customer,
      ai_status: 'FALLBACK',
      customer_category: customer.business_type,
      needs_summary: `[AI unavailable - manual review needed] ${customer.customer_goals}`,
      onboarding_plan: 'Our onboarding team will review your submission and tailor your plan. In the meantime, please complete the steps below.',
      clarification_questions: [
        'Could you share more detail about your goals and any onboarding challenges?'
      ],
      tasks: [
        {
          task_title: 'Confirm your business details',
          task_description: 'Reply to confirm your business details and goals so our team can tailor your onboarding.',
          responsible_party: 'CUSTOMER',
          priority: 'HIGH'
        },
        {
          task_title: 'Onboarding team review',
          task_description: 'Our team will manually review your submission and prepare a personalised plan.',
          responsible_party: 'ONBOARDING_TEAM',
          priority: 'HIGH'
        },
        {
          task_title: 'Specialist check of regulatory or certification questions',
          task_description: 'A specialist will verify any regulatory or certification matters relevant to your business.',
          responsible_party: 'HUMAN_SPECIALIST',
          priority: 'MEDIUM'
        }
      ]
    }
  };
}

try {
  // Retrieve Gemini response
  let response = $json.output ?? $json.text ?? $json.response ?? $json;

  // Handle JSON returned as text
  if (typeof response === 'string') {
    response = response
      .replace(/^```json\s*/i, '')
      .replace(/\s*```$/, '');
    response = JSON.parse(response);
  }

  // Handle nested output structures
  const analysis = response.output ?? response;

  // Validate AI response
  for (const field of ['customer_category', 'needs_summary', 'onboarding_plan']) {
    if (!analysis[field]) throw new Error(`AI response missing: ${field}`);
  }

  if (!Array.isArray(analysis.tasks) || analysis.tasks.length === 0) {
    throw new Error('AI did not generate onboarding tasks.');
  }

  for (const task of analysis.tasks) {
    if (!task.task_title || !task.task_description || !task.responsible_party || !task.priority) {
      throw new Error('One or more AI-generated tasks are incomplete.');
    }
  }

  return {
    json: {
      ...customer,
      ai_status: 'OK',
      customer_category: analysis.customer_category,
      needs_summary: analysis.needs_summary,
      onboarding_plan: analysis.onboarding_plan,
      clarification_questions: analysis.clarification_questions || [],
      tasks: analysis.tasks
    }
  };
} catch (error) {
  return fallback(error.message);
}

const stamp = () => new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Africa/Lagos', year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', hour12: false
}).format(new Date());   // e.g. 2026-11-23 09:10 (Lagos time)

// Get submitted form data
const input = $json;

// Support both direct form fields and nested body fields
const data = input.body && typeof input.body === 'object'
  ? { ...input, ...input.body }
  : input;

// Normalise field names to handle spaces and different naming formats
function normaliseKey(key) {
  return key.toLowerCase().replace(/[^a-z0-9]/g, '');
}

const fields = {};
for (const [key, value] of Object.entries(data)) {
  fields[normaliseKey(key)] = value;
}

// Retrieve values using alternative field names
function getField(...names) {
  for (const name of names) {
    const value = fields[normaliseKey(name)];
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      return String(value).trim();
    }
  }
  return '';
}

// Extract and standardise customer information
const customer = {
  customer_id: `CUS-${Date.now()}-${Math.floor(Math.random() * 10000)}`,
  created_at: stamp(),

  business_name: getField('Business Name', 'businessName'),
  contact_name: getField('Contact Person Name', 'Contact Name', 'contactName'),
  email: getField('Email Address', 'Email', 'email').toLowerCase(),
  business_type: getField('Business Type', 'businessType'),
  country_location: getField('Country / Location', 'Country Location', 'Location'),
  customer_goals: getField('What do you want to achieve?', 'Customer Goals', 'Goals'),
  onboarding_challenges: getField('Specific Onboarding Challenges', 'Onboarding Challenges', 'Challenges'),

  onboarding_status: 'PENDING',
  welcome_email_status: 'PENDING'
};

// Validate required fields
const requiredFields = [
  'business_name',
  'contact_name',
  'email',
  'business_type',
  'country_location',
  'customer_goals'
];

const validationErrors = [];

for (const field of requiredFields) {
  if (!customer[field]) {
    validationErrors.push(`${field} is required`);
  }
}

// Validate email format
const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (customer.email && !emailPattern.test(customer.email)) {
  validationErrors.push('Invalid email address');
}

// Validate business category
const allowedTypes = [
  'exporter',
  'farmer',
  'cooperative',
  'certifier'
];

if (
  customer.business_type &&
  !allowedTypes.includes(customer.business_type.toLowerCase())
) {
  validationErrors.push('Invalid business type');
}

// Return standardised customer data
return {
  json: {
    ...customer,
    is_valid: validationErrors.length === 0,
    validation_errors: validationErrors
  }
};

const customer = $json;

const subject = `Welcome to the onboarding programme, ${customer.business_name}`;

// Give every task a target date (also reused when tasks are saved)
const daysByPriority = { HIGH: 3, MEDIUM: 7, LOW: 10 };
const tasks = customer.tasks.map(task => {
  const priority = String(task.priority || 'MEDIUM').toUpperCase();
  const due = new Date();
  due.setDate(due.getDate() + (daysByPriority[priority] ?? 7));
  return { ...task, priority, due_date: due.toISOString().split('T')[0] };
});

const owner = {
  ONBOARDING_TEAM: 'our onboarding team',
  HUMAN_SPECIALIST: 'one of our specialists'
};

const customerTasks = tasks.filter(t => t.responsible_party === 'CUSTOMER');
const teamTasks = tasks.filter(t => t.responsible_party !== 'CUSTOMER');

const needs = customer.ai_status === 'FALLBACK'
  ? customer.customer_goals
  : customer.needs_summary;

const youList = customerTasks.length
  ? customerTasks.map((t, i) =>
      `${i + 1}. ${t.task_title}\n   ${t.task_description}\n   Please complete by: ${t.due_date}`
    ).join('\n\n')
  : 'Nothing is needed from you right now.';

const teamList = teamTasks.length
  ? teamTasks.map((t, i) =>
      `${i + 1}. ${t.task_title}\n   ${t.task_description}\n   Handled by ${owner[t.responsible_party] || 'our team'}`
    ).join('\n\n')
  : 'We will be in touch with any further steps.';

const questions = customer.clarification_questions?.length
  ? `\nQUESTIONS WE'D LIKE YOU TO ANSWER\n${customer.clarification_questions.map((q, i) => `${i + 1}. ${q}`).join('\n')}\n\nSimply reply to this email with your answers.\n`
  : '';

const body = `Hello ${customer.contact_name},

Thank you for registering ${customer.business_name}. We have reviewed your submission and prepared a starting plan.

WHAT YOU TOLD US
${needs}

YOUR ONBOARDING PLAN
${customer.onboarding_plan}

WHAT WE NEED FROM YOU
${youList}

WHAT OUR TEAM WILL DO
${teamList}
${questions}
Please note that this is an independent onboarding prototype. Any regulatory or compliance matters will require human verification.

Kind regards,
Customer Onboarding Team
`;

return {
  json: {
    ...customer,
    tasks,
    welcome_email_subject: subject,
    welcome_email_body: body,
    welcome_email_status: 'PENDING'
  }
};

const stamp = () => new Intl.DateTimeFormat('sv-SE', {
  timeZone: 'Africa/Lagos', year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', hour12: false
}).format(new Date());   // e.g. 2026-11-23 09:10 (Lagos time)

const customer = $('Prepare Welcome Email').first().json;

const tasks = customer.tasks;

if (!Array.isArray(tasks) || tasks.length === 0) {
  throw new Error('No onboarding tasks available.');
}

return tasks.map((task, index) => ({
  json: {
    task_id: `${customer.customer_id}-TSK-${index + 1}`,
    customer_id: customer.customer_id,
    task_title: task.task_title,
    task_description: task.task_description,
    responsible_party: task.responsible_party,
    due_date: task.due_date,
    status: 'PENDING',
    created_at: stamp(),
    completed_at: ''
  }
}));
